import copy

import pytest
from hypothesis import given
from hypothesis.strategies import composite as hyp_composite
import hypothesis.strategies as st

from intervals import merge_intervals


def reference_merge(intervals):
    # Obviously-correct reference: sort then merge iff overlap/touch (start <= cur_end).
    for s, e in intervals:
        if s > e:
            raise ValueError("bad")
    if not intervals:
        return []
    ordered = sorted(intervals, key=lambda x: (x[0], x[1]))
    out = []
    cs, ce = ordered[0]
    for s, e in ordered[1:]:
        if s <= ce:
            if e > ce:
                ce = e
        else:
            out.append((cs, ce))
            cs, ce = s, e
    out.append((cs, ce))
    return out


def coverage(intervals):
    pts = set()
    for s, e in intervals:
        for p in range(s, e + 1):
            pts.add(p)
    return pts


valid_interval = st.builds(
    lambda s, l: (s, s + l),
    st.integers(min_value=-20, max_value=20),
    st.integers(min_value=0, max_value=10),
)
valid_lists_small = st.lists(valid_interval, min_size=0, max_size=15)
valid_lists_large = st.lists(valid_interval, min_size=41, max_size=60)


# ---- explicit spec examples ----

def test_example_basic():
    assert merge_intervals([(1, 3), (2, 6), (8, 10), (15, 18)]) == [(1, 6), (8, 10), (15, 18)]


def test_example_touch_merges():
    assert merge_intervals([(1, 3), (3, 5)]) == [(1, 5)]


def test_example_adjacent_stays_separate():
    assert merge_intervals([(1, 3), (4, 5)]) == [(1, 3), (4, 5)]


def test_example_unsorted():
    assert merge_intervals([(5, 7), (1, 2)]) == [(1, 2), (5, 7)]


def test_example_empty():
    assert merge_intervals([]) == []


def test_example_invalid_raises():
    with pytest.raises(ValueError):
        merge_intervals([(3, 1)])


def test_single_point_valid():
    assert merge_intervals([(2, 2)]) == [(2, 2)]


def test_single_point_touch_merges():
    assert merge_intervals([(2, 2), (2, 2)]) == [(2, 2)]
    assert merge_intervals([(1, 2), (2, 2)]) == [(1, 2)]
    assert merge_intervals([(2, 2), (3, 4)]) == [(2, 2), (3, 4)]


def test_contained_absorbed():
    assert merge_intervals([(1, 10), (2, 3)]) == [(1, 10)]
    assert merge_intervals([(2, 3), (1, 10)]) == [(1, 10)]


def test_transitive_chain_collapses():
    assert merge_intervals([(1, 2), (2, 3), (3, 4)]) == [(1, 4)]
    assert merge_intervals([(5, 6), (1, 2), (2, 5)]) == [(1, 6)]


def test_duplicates_collapse():
    assert merge_intervals([(1, 3), (1, 3)]) == [(1, 3)]


def test_negative_and_zero():
    assert merge_intervals([(-5, -3), (-3, 0), (1, 2)]) == [(-5, 0), (1, 2)]
    assert merge_intervals([(-5, -3), (-2, 0)]) == [(-5, -3), (-2, 0)]


def test_large_adjacent_must_stay_separate():
    # Triggers len > 40 branch in implementation; adjacent must NOT merge.
    ivs = [(i * 10, i * 10 + 3) for i in range(50)]
    # gap between consecutive: e.g. (0,3),(10,13): 10 > 3, disjoint & non-touching
    expected = sorted(ivs)
    assert merge_intervals(ivs) == expected


def test_large_touch_chain_collapses():
    ivs = [(i * 2, i * 2 + 2) for i in range(50)]
    # each touches next: (0,2),(2,4),(4,6),...
    assert merge_intervals(ivs) == [(0, 2 * 49 + 2)]


def test_large_adjacent_single_gap_not_merged():
    # 41 copies pattern where every pair is merely adjacent (gap of 1 integer step).
    ivs = [(2 * i, 2 * i + 1) for i in range(45)]
    # e.g. (0,1),(2,3): share no point, must stay separate
    assert merge_intervals(ivs) == sorted(ivs)


def test_large_mixed_adjacent_and_overlap():
    ivs = [(0, 1)] * 20 + [(2, 3)] * 25
    # (0,1) and (2,3) are adjacent, not overlapping -> two groups
    assert merge_intervals(ivs) == [(0, 1), (2, 3)]


def test_invalid_raises_any_position():
    with pytest.raises(ValueError):
        merge_intervals([(1, 2), (5, 4)])
    with pytest.raises(ValueError):
        merge_intervals([(5, 4), (1, 2)])
    with pytest.raises(ValueError):
        merge_intervals([(1, 1), (2, 2), (9, 3)])


def test_empty_returns_new_list():
    out = merge_intervals([])
    assert out == []
    assert isinstance(out, list)


def test_returns_new_list_of_tuples_sorted():
    inp = [(3, 5), (1, 2)]
    out = merge_intervals(inp)
    assert out == [(1, 2), (3, 5)]
    assert all(isinstance(x, tuple) for x in out)
    # mutating output must not affect a second call
    out.append((99, 100))
    assert merge_intervals(inp) == [(1, 2), (3, 5)]


def test_input_not_mutated():
    inp = [(3, 5), (1, 2), (2, 4)]
    snapshot = copy.deepcopy(inp)
    merge_intervals(inp)
    assert inp == snapshot


def test_input_elements_not_mutated_large():
    inp = [(i, i + 1) for i in range(50)]
    snapshot = copy.deepcopy(inp)
    merge_intervals(inp)
    assert inp == snapshot


@given(valid_lists_small)
def test_output_sorted_and_strictly_disjoint(intervals):
    out = merge_intervals(intervals)
    for i in range(1, len(out)):
        assert out[i][0] > out[i - 1][0] or (out[i][0] == out[i - 1][0] and False)
        assert out[i][0] > out[i - 1][1]
    starts = [s for s, _ in out]
    assert starts == sorted(starts)
    for s, e in out:
        assert s <= e


@given(valid_lists_small)
def test_coverage_preserved(intervals):
    out = merge_intervals(intervals)
    assert coverage(out) == coverage(intervals)


@given(valid_lists_small)
def test_matches_reference_model(intervals):
    assert merge_intervals(intervals) == reference_merge(intervals)


@given(valid_lists_large)
def test_matches_reference_model_large(intervals):
    assert merge_intervals(intervals) == reference_merge(intervals)


@given(valid_lists_large)
def test_large_output_disjoint(intervals):
    out = merge_intervals(intervals)
    for i in range(1, len(out)):
        assert out[i][0] > out[i - 1][1]


@given(valid_lists_small)
def test_idempotence(intervals):
    once = merge_intervals(intervals)
    twice = merge_intervals(once)
    assert twice == once


@given(valid_lists_small)
def test_output_intervals_are_tuples_of_ints(intervals):
    out = merge_intervals(intervals)
    assert isinstance(out, list)
    for item in out:
        assert isinstance(item, tuple)
        assert len(item) == 2


@given(st.lists(st.tuples(st.integers(min_value=-10, max_value=10), st.integers(min_value=-10, max_value=10)), min_size=1, max_size=10))
def test_invalid_anywhere_raises(intervals):
    if any(s > e for s, e in intervals):
        with pytest.raises(ValueError):
            merge_intervals(intervals)
    else:
        merge_intervals(intervals)


@given(valid_lists_small)
def test_permutation_invariance(intervals):
    out1 = merge_intervals(intervals)
    out2 = merge_intervals(list(reversed(intervals)))
    assert out1 == out2


@given(valid_lists_small)
def test_duplicate_idempotence(intervals):
    assert merge_intervals(intervals + intervals) == merge_intervals(intervals)
